class Solution {
    public String sortString(String text){
        int[] count=new int[26];
        for(char value:text.toCharArray())count[value-'a']++;
        StringBuilder answer=new StringBuilder();
        while(answer.length()<text.length()){
            for(int i=0;i<26;i++)if(count[i]>0){
                answer.append((char)('a'+i));
                count[i]--;
            }
            for(int i=25;i>=0;i--)if(count[i]>0){
                answer.append((char)('a'+i));
                count[i]--;
            }
        }
        return answer.toString();
    }
}

code.kotlin:
class Solution {
    fun sortString(text:String):String{
        val count=IntArray(26);
        for(value in text)count[value-'a']++;
        val answer=StringBuilder();
        while(answer.length<text.length){
            for(i in 0..25)if(count[i]>0){
                answer.append(('a'.code+i).toChar());
                count[i]--
            };
            for(i in 25 downTo 0)if(count[i]>0){
                answer.append(('a'.code+i).toChar());
                count[i]--
            }
        };
        return answer.toString()
    }
}

